import json
from pathlib import Path

root=Path(__file__).resolve().parents[1]
path=root/'src/data/privacy-policy.json'
policy=json.loads(path.read_text(encoding='utf-8'))
policy['version']='2026-11-06.4'
policy['sections']=[
{'title':'1. Общие положения','text':'Настоящая политика описывает, какие данные используются в мобильном приложении «КодШаг: учим программирование», для чего они нужны, где хранятся и как их можно удалить. Разработчик и лицо, ответственное за обработку данных в рамках своей деятельности: Денисов Максим Сергеевич, физическое лицо, применяющее налог на профессиональный доход — самозанятый. Контакт по вопросам конфиденциальности и поддержки: maks.denisov.dev@outlook.com. В приложении нет регистрации и синхронизации аккаунта между устройствами. Для обучения не требуется указывать имя, номер телефона или адрес электронной почты.'},
{'title':'2. Какие данные сохраняются на устройстве','text':'Для работы приложения на устройстве сохраняются:\n• ответы и черновики опросов;\n• созданные пользователем темы и вопросы;\n• отметки знакомых вопросов;\n• профессии и выбранные для них курсы;\n• прогресс, результаты прохождения курсов и задания для работы над ошибками;\n• история занятий, серия дней обучения и заморозки серии;\n• настройки оформления и уведомлений;\n• скачанные учебные материалы;\n• журнал последних 100 уведомлений и отметки об их прочтении;\n• редакция политики конфиденциальности и дисклеймера, с которыми пользователь ознакомился, и время подтверждения ознакомления.\nЭти сведения используются для продолжения обучения, отображения результатов и сохранения настроек.'},
{'title':'3. Хранение учебных данных','text':'Ответы, прогресс и настройки хранятся локально, в хранилище приложения на устройстве пользователя. Автоматическая передача этих сведений разработчику и синхронизация между устройствами не предусмотрены. Данные сохраняются до их изменения или удаления пользователем либо очистки хранилища приложения. При выборе «Удалить только материалы» ответы и прогресс сохраняются. Вариант «Удалить курс и все его данные» удаляет скачанные материалы, ответы, результаты, состояние интерактивных заданий, работу над ошибками и прогресс курса, а также сбрасывает его отметки прохождения в профессиях. Полное удаление требует отдельного подтверждения. Общая история занятий и серия дней обучения сохраняются. Не указывайте в свободных ответах пароли, платёжные реквизиты и персональные данные других людей.'},
{'title':'4. Интернет и загрузка материалов','text':'При подключении к интернету приложение проверяет наличие новых учебных материалов. Курсы скачиваются и обновляются по действию пользователя. Скачанные материалы доступны без интернета. Для размещения и загрузки материалов используются сервисы GitHub и Яндекса. При обращении к ним могут передаваться IP-адрес, адрес запрашиваемого ресурса, время запроса и технические сведения о соединении. Обработка и сроки хранения журналов соединений определяются соответствующими провайдерами. Ответы пользователя, созданные им темы, профессии и учебный прогресс в запросы обновлений не включаются.'},
{'title':'5. Учебные материалы и реклама','text':'Отметка «Создано с помощью ИИ» относится к подготовке учебных материалов. В приложении показывается реклама Яндекса. Для этого используется рекламный модуль Yandex Mobile Ads, в состав которого входят компоненты AppMetrica. Приложение не запрашивает разрешение на подбор рекламы по интересам и не передаёт рекламному сервису согласие на такую обработку. Отправка дополнительных аналитических отчётов рекламного модуля отключена. Для загрузки рекламы, учёта показов, диагностики и защиты от мошенничества рекламный сервис может обрабатывать IP-адрес, технические сведения об устройстве и соединении, информацию о показах и взаимодействиях с объявлениями. Использование рекламных и иных идентификаторов устройства определяется настройками устройства, правилами рекламного сервиса и применимыми требованиями. Ответы на вопросы, написанный код, профессии и учебный прогресс не передаются рекламному сервису. Доступ к геолокации для рекламы отключён, разрешение на определение местоположения не запрашивается. Отдельная аналитика действий пользователя на учебных экранах не настроена. Подробнее об обработке данных рекламным сервисом — в политике конфиденциальности Яндекса: https://yandex.ru/legal/confidential/ru/. Покупки курсов и обработка платёжных данных в приложении не предусмотрены.'},
{'title':'6. Уведомления','text':'Уведомления о новых и обновлённых материалах формируются на устройстве. По желанию пользователя приложение периодически проверяет обновления в фоне, в том числе когда закрыто. Для этого приложение обращается к каталогу материалов. При таких запросах могут передаваться технические сведения, описанные в разделе 4. Системные уведомления включаются по действию пользователя. При необходимости приложение запрашивает разрешение Android на их показ. Фоновые проверки можно отключить в разделе уведомлений приложения. Разрешение на показ уведомлений также можно изменить в системных настройках Android.'},
{'title':'7. Экспорт ответов и обращения в поддержку','text':'При сохранении, печати или отправке конспекта пользователь самостоятельно выбирает действие, приложение и получателя. Созданные и отправленные копии документов хранятся отдельно от данных приложения. Поддержка работает через электронную почту. При отправке обращения разработчик получает адрес электронной почты отправителя, текст сообщения и вложения, которые пользователь добавил самостоятельно. Ответы и учебный прогресс автоматически к письму не прикрепляются. Эти сведения используются для рассмотрения обращения и подготовки ответа. Переписка проходит через почтовые сервисы отправителя и поддержки, включая Outlook/Microsoft. Обращения хранятся в течение времени, необходимого для решения вопроса и выполнения связанных с ним обязательств. Запросить удаление переписки можно по адресу maks.denisov.dev@outlook.com. При удалении учитываются применимые требования законодательства и возможности почтовых сервисов.'},
{'title':'8. Защита данных','text':'Для загрузки опубликованных материалов используется защищённое соединение HTTPS. Скачанные пакеты курсов проверяются по размеру, контрольной сумме и формату. Разработчик не публикует учебные данные пользователя и не получает их автоматически. Автоматическое резервное копирование приложения средствами Android отключено. Приложение не предоставляет отдельного шифрования пользовательских ответов. Защита локальных данных зависит от настроек безопасности устройства и операционной системы. Рекомендуется использовать блокировку устройства. Экспортированные документы, отправленные письма и самостоятельно созданные резервные копии могут храниться вне контроля приложения.'},
{'title':'9. Удаление данных и обращения пользователя','text':'Для удаления всех локальных сохранений очистите хранилище приложения в системных настройках Android или удалите приложение. Для удаления данных отдельного курса используйте вариант «Удалить курс и все его данные» на его карточке и подтвердите действие. Очистка только кеша может не удалить ответы, прогресс и настройки. Экспортированные документы и почтовую переписку необходимо удалять отдельно. Разработчик не может удалённо прочитать или восстановить сведения, которые хранятся только на устройстве пользователя. По вопросам обработки данных, а также для уточнения, блокирования или удаления сведений, переданных разработчику, можно обратиться по адресу maks.denisov.dev@outlook.com. По вопросам данных, обрабатываемых рекламным или другим внешним сервисом, можно обратиться к соответствующему сервису. Пользователь также вправе обратиться в уполномоченный орган по защите прав субъектов персональных данных или в суд.'},
{'title':'10. Ознакомление с политикой и её изменения','text':'При первом запуске приложение показывает дисклеймер и политику конфиденциальности с подтверждением ознакомления. Подтверждение сохраняется на устройстве. Подтверждение ознакомления не является универсальным согласием на любые виды обработки данных, рекламу или рассылки. Если пользователь не подтверждает ознакомление, обучение не открывается, но документы остаются доступны для чтения. Политика доступна без интернета в разделе «Личный кабинет → Помощь и информация → Политика конфиденциальности». При существенном изменении условий обработки данных разработчик обновляет дату и редакцию политики. Приложение повторно запрашивает подтверждение ознакомления.'}
]
path.write_text(json.dumps(policy,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
text='# Политика конфиденциальности приложения «КодШаг»\n\nДата обновления: '+policy['date']+'\n\n'+'\n\n'.join('## '+s['title']+'\n\n'+s['text'] for s in policy['sections'])+'\n'
(root/'artifacts/privacy-policy-mobile.md').write_text(text,encoding='utf-8')
print('Mobile privacy policy finalized: '+policy['version'])
